import { getCustomer } from './customers.js';
import { lineTotal, lineDiscount, invoiceTotals } from './invoices.js';
import { formatEuros } from './money.js';

/**
 * Render an invoice as plain text.
 * @param {{ customerId: string, number?: string, lines: Array<{ qty: number, name: string, unitPrice: number, discountPercent?: number }> }} invoice
 * @returns {string}
 */
export function renderInvoiceText(invoice) {
  const number = invoice.number ?? 'DRAFT';
  const customerResult = getCustomer(invoice.customerId);
  const customerName = customerResult.ok ? customerResult.value.name : 'Unknown Customer';
  const totals = invoiceTotals(invoice);

  const lines = [];
  lines.push(number);
  lines.push(customerName);
  lines.push('');

  for (const line of invoice.lines) {
    const total = lineTotal(line);
    if (line.discountPercent) {
      const discount = lineDiscount(line);
      const netTotal = total - discount;
      const lineText = `${line.qty} × ${line.name} @ ${formatEuros(line.unitPrice)} = ${formatEuros(total)} - ${formatEuros(discount)} = ${formatEuros(netTotal)}`;
      lines.push(lineText);
    } else {
      const lineText = `${line.qty} × ${line.name} @ ${formatEuros(line.unitPrice)} = ${formatEuros(total)}`;
      lines.push(lineText);
    }
  }

  lines.push('');
  if (totals.discount > 0) {
    lines.push(`Subtotal: ${formatEuros(totals.subtotal)}`);
    lines.push(`Discount: -${formatEuros(totals.discount)}`);
  }
  lines.push(`Total: ${formatEuros(totals.total)}`);

  return lines.join('\n');
}

